"""Replay both actual C cores and all output fields over saved native MMIO."""
import argparse,hashlib,json,subprocess
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('--native',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();assert not a.output.exists();a.output.mkdir(parents=True);W=Path(__file__).resolve().parent
s=json.loads(a.native.read_text());row=s['jobs']['spi-prepare'];q=json.loads(row['receipt']['output']);assert q['ok'];r=q['result'];e=r['engine'];assert r['operation_code']==r['restore_error']==e['operation_code']==e['restore_error']==0 and r['restored']==e['restored']==1
outer={'Code':r['operation_code'],'RestoreError':r['restore_error'],'Restored':r['restored'],'Stage':r['stage'],'Reads':r['register_reads'],'Writes':r['register_write_attempts'],'TraceCount':len(r['trace']),'DirtyPins':r['dirty_pins'],'VoteDirty':r['vote_dirty'],'BeforeClock':r['clock_before'],'AfterClock':r['clock_after'],'BeforePins':r['pins_before'],'DuringPins':r['pins_during'],'AfterPins':r['pins_after'],'Identity':r['identity'],'VoteEnabled':r['enabled_vote']}
engine={'Code':e['operation_code'],'RestoreError':e['restore_error'],'Restored':e['restored'],'Stage':e['stage'],'Reads':e['register_reads'],'Writes':e['register_write_attempts'],'TraceCount':len(e['trace']),'Dirty':e['dirty'],'Before':e['before'],'During':e['during'],'After':e['after'],'DfsBefore':e['DFS_before'],'DfsAfter':e['DFS_after'],'Index':e['clock_index'],'SourceHz':e['source_hz'],'BusHz':e['bus_hz'],'GuardBefore':e['guards_before'],'GuardAfter':e['guards_after']}
def fields(d):return ''.join('.'+k+'='+('{'+','.join(map(str,v))+'}'if isinstance(v,list)else str(v))+',\n'for k,v in d.items())
def trace(rows):return '{'+','.join('{%d,0x%x,0x%x}'%(e['kind'],int(e['address'],16),e['value'])for e in rows)+'}'
text='static const G37_SPI_RESULT Expected={\n'+fields(outer)+'.Trace='+trace(r['trace'])+',\n.Engine={'+fields(engine)+'.Trace='+trace(e['trace'])+'}};\n';(a.output/'spi-native-fixture.h').write_text(text)
exe=a.output/'replay';subprocess.run(['clang','-std=c11','-O1','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-fno-omit-frame-pointer','-I',str(a.output.resolve()),str(W/'g37_spi.c'),str(W/'g37_engine.c'),str(W/'replay-spi.c'),'-o',str(exe.resolve())],check=True,capture_output=True,text=True)
run=subprocess.run([str(exe.resolve())],capture_output=True,text=True);assert run.returncode==0 and not run.stderr,(run.returncode,run.stdout,run.stderr);report=json.loads(run.stdout)
report.update(core_sha256={p.name:hashlib.sha256(p.read_bytes()).hexdigest()for p in[W/'g37_spi.c',W/'g37_engine.c']},native_state_sha256=hashlib.sha256(a.native.read_bytes()).hexdigest(),native_job=row['id'],ASan_UBSan=True,all_output_fields_and_reads_writes_match=True,native_commands_submitted=0,limits=['MMIO boundaries replay recorded values; native receipts separately establish actual register access.'])
(a.output/'replay.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report))
